const settleReservationRow = `-- name: SettleReservationRow :execrows
UPDATE org_asset_reservations SET state=$1::text,revision=revision+1,end_cause='TIME'
WHERE org_id=CAST($2::text AS uuid) AND id=CAST($3::text AS uuid) AND state=$4::text AND revision=$5::bigint
`

type SettleReservationRowParams struct {
	State     string `json:"state"`
	OrgID     string `json:"org_id"`
	ID        string `json:"id"`
	FromState string `json:"from_state"`
	Revision  int64  `json:"revision"`
}

// Compare-and-set of one time-driven outcome: a repeat changes nothing.
func (q *Queries) SettleReservationRow(ctx context.Context, arg SettleReservationRowParams) (int64, error) {
	result, err := q.db.Exec(ctx, settleReservationRow,
		arg.State,
		arg.OrgID,
		arg.ID,
		arg.FromState,
		arg.Revision,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
